app.post('/api/salvar', async (req, res) => {
  try {
    const dados = req.body;
    // Validação dos dados (exemplo):
    if (!dados.nome) {
      return res.status(400).json({ sucesso: false, mensagem: "Campo nome é obrigatório." });
    }

    // Simular salvar no banco
    await salvarNoBanco(dados);

    return res.json({ sucesso: true, mensagem: "Gravado com sucesso" });
  } catch (error) {
    console.error('Erro ao salvar:', error);
    return res.status(500).json({ sucesso: false, mensagem: "Erro interno ao salvar." });
  }
});
```

